import path from 'path';
import { OUTPUT_DIR, PLATFORM_VERSION } from './constants.js';
import { UnifiedAppAuthTypes, UnifiedAppDistributionTypes } from './types.js';
import { isUnifiedAppConfig } from './utils.js';
export class DevServerState {
    _expressPort;
    _functionsConfig;
    _localDevUrlMapping;
    _outputDir;
    _appPath;
    _extensionsMetadata;
    _portalId;
    _sdkVersionOverride;
    _mutableState = {};
    logger;
    appConfig;
    constructor({ localDevUrlMapping, extensionConfigs, accountId, expressPort, platformVersion, logger, urls, appConfig, appFunctions, appId, sdkVersionOverride, }) {
        if (!extensionConfigs) {
            throw new Error('Unable to load the required extension configuration files');
        }
        const extensionsMetadata = [];
        extensionConfigs.forEach((config) => {
            const { appName, title, sourceId } = config.data;
            extensionsMetadata.push({
                config,
                baseMessage: {
                    appName,
                    title,
                    sourceId,
                    callback: `http://hslocal.net:${expressPort}/${config.output}`,
                    portalId: accountId,
                    ...(appId !== undefined && { appId }),
                },
            });
        });
        this._expressPort = expressPort;
        this._extensionsMetadata = extensionsMetadata;
        this._appPath = extensionConfigs[0].path;
        this._portalId = accountId;
        this._outputDir = path.join(this._appPath, OUTPUT_DIR);
        // Pass options from the CLI for running app functions locally
        this._functionsConfig = {
            app: { path: this._appPath },
            accountId,
            platformVersion,
            hubspotApiOrigin: urls.api,
            hubspotWebsiteOrigin: urls.web,
            appFunctions,
        };
        this._localDevUrlMapping = localDevUrlMapping;
        this._sdkVersionOverride = sdkVersionOverride;
        this.logger = logger;
        this.appConfig = appConfig;
        Object.freeze(this);
    }
    get portalId() {
        return this._portalId;
    }
    get sdkVersionOverride() {
        return this._sdkVersionOverride;
    }
    get expressPort() {
        return this._expressPort;
    }
    get extensionsMetadata() {
        return this._extensionsMetadata;
    }
    get functionsConfig() {
        return this._functionsConfig;
    }
    get outputDir() {
        return this._outputDir;
    }
    get appPath() {
        return this._appPath;
    }
    get localDevUrlMapping() {
        return this._localDevUrlMapping;
    }
    get extensionsWebSocket() {
        return this._mutableState.extensionsWebSocket;
    }
    set extensionsWebSocket(ws) {
        this._mutableState.extensionsWebSocket = ws;
    }
    getExtensionsWebSocket() {
        if (!this._mutableState.extensionsWebSocket) {
            throw new Error('ExtensionsWebSocket not initialized. Server must be started first.');
        }
        return this._mutableState.extensionsWebSocket;
    }
    /**
     * In legacy apps, there was a difference between public and private apps at the project level.
     * In unified apps, this is no longer applied and all apps are considered "public".
     * However, to support serverless for some 2026.03 apps we need to consider an app to be private if it has static auth and private distribution.
     * For other unified apps we continue to mark them public (despite auth/dist settings) to maintain current behavior.
     * @returns
     */
    isPublicApp() {
        if (this.appConfig && isUnifiedAppConfig(this.appConfig)) {
            const platformVersion = this._functionsConfig.platformVersion;
            const isUnifiedServerlessVersion = platformVersion === PLATFORM_VERSION.V202603 ||
                platformVersion === PLATFORM_VERSION.V202603BETA ||
                platformVersion === PLATFORM_VERSION.V202609 ||
                platformVersion === PLATFORM_VERSION.V202609BETA ||
                platformVersion === PLATFORM_VERSION.V202703 ||
                platformVersion === PLATFORM_VERSION.V202703BETA ||
                platformVersion === PLATFORM_VERSION.UNSTABLE;
            if (isUnifiedServerlessVersion &&
                this.appConfig.distribution === UnifiedAppDistributionTypes.PRIVATE &&
                this.appConfig.auth?.type === UnifiedAppAuthTypes.STATIC) {
                return false;
            }
            return true;
        }
        return !!this.appConfig?.isPublicApp;
    }
    get authType() {
        if (this.appConfig && isUnifiedAppConfig(this.appConfig)) {
            return this.appConfig.auth.type;
        }
        return undefined;
    }
    get distribution() {
        if (this.appConfig && isUnifiedAppConfig(this.appConfig)) {
            return this.appConfig.distribution;
        }
        return undefined;
    }
    setWebSocketSetupCallback(callback) {
        this._mutableState.webSocketSetupCallback = callback;
    }
    triggerWebSocketSetup() {
        if (this._mutableState.webSocketSetupCallback) {
            this._mutableState.webSocketSetupCallback();
            this._mutableState.webSocketSetupCallback = undefined;
        }
    }
}
